from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, KeepTogether
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.pdfbase import pdfmetrics
from pathlib import Path

out = Path('output/pdf'); out.mkdir(parents=True, exist_ok=True)
pdf = out / 'manual-configuracao-rb-mikrotik-manos-tech.pdf'
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleBlue', parent=styles['Title'], textColor=colors.HexColor('#075985'), fontSize=22, leading=27, spaceAfter=12))
styles.add(ParagraphStyle(name='H', parent=styles['Heading2'], textColor=colors.HexColor('#075985'), fontSize=14, leading=18, spaceBefore=10, spaceAfter=6))
styles.add(ParagraphStyle(name='Body2', parent=styles['BodyText'], fontSize=10.5, leading=15, spaceAfter=6))
styles.add(ParagraphStyle(name='Code2', parent=styles['Code'], fontName='Courier', fontSize=8.5, leading=12, backColor=colors.HexColor('#eef2f7'), borderPadding=7, spaceBefore=5, spaceAfter=8))

def footer(canvas, doc):
    canvas.saveState(); canvas.setFont('Helvetica', 8); canvas.setFillColor(colors.grey)
    canvas.drawString(18*mm, 12*mm, 'Manos Tech - Configuracao MikroTik HotSpot')
    canvas.drawRightString(192*mm, 12*mm, f'Pagina {doc.page}')
    canvas.restoreState()

story = [Paragraph('Configuracao do HotSpot MikroTik', styles['TitleBlue']), Paragraph('Passo a passo para a RB cadastrada no sistema Manos Tech', styles['Body2']), Spacer(1, 5*mm)]
story += [Paragraph('Antes de iniciar', styles['H']), Paragraph('Confirme a RB e a identidade cadastrada no painel. Baixe o kit-base, a ativacao personalizada para aquela RB, o heartbeat personalizado e os arquivos HTML atuais. Nunca importe um arquivo de ativacao generico. Antes de qualquer reset, faca backup/export da configuracao e confirme que a unidade pode ser reconfigurada: o reset apaga configuracoes existentes e nao e necessario para atualizar uma RB ja preparada.', styles['Body2'])]
story += [Paragraph('1. Preparar acesso e backup', styles['H']), Paragraph('Use RouterOS v7 atualizado e WinBox por MAC em uma rede local. Salve um backup pelo WinBox e exporte a configuracao atual. Se for uma RB reutilizada, identifique pontes, DHCP, enderecos, firewall e servicos existentes antes de importar o kit; nao apague a configuracao sem janela de manutencao e autorizacao do responsavel.', styles['Body2'])]
story += [Paragraph('2. Reset (somente RB nova/autorizada)', styles['H']), Paragraph('Este comando e destrutivo. Use somente apos salvar o backup e confirmar que a configuracao atual pode ser apagada. Prefira confirmar a operacao manualmente no prompt do RouterOS.', styles['Body2']), Paragraph('/system reset-configuration no-defaults=yes', styles['Code2']), Paragraph('Apos reiniciar, reconecte pelo endereco MAC, defina senha forte e mantenha a sessao local de recuperacao disponivel.', styles['Body2'])]
story += [Paragraph('3. Separar os arquivos corretos', styles['H']), Paragraph('Use somente o kit-base e os arquivos personalizados de Ativacao e Heartbeat baixados agora para esta RB. Os arquivos HTML login.html e alogin.html sao os publicados junto do kit. Nao reutilize downloads antigos nem use o botao Reset HTML depois de enviar os arquivos Manos Tech, pois ele recria as paginas padrao do RouterOS.', styles['Body2'])]
story += [Paragraph('4. Topologia das portas', styles['H']), Paragraph('<b>ether1</b> recebe a entrada do provedor. <b>ether2 e ether3</b> ficam no HotSpot para visitantes. <b>ether4</b> fica na rede livre dos funcionarios em 192.168.89.0/24. <b>ether5</b> fica na mesma rede de camada 2 do provedor, como extensao direta da ether1, sem HotSpot, DHCP ou NAT privado da RB. A faixa de IP da ether5 nao e fixa: ela vem do provedor.', styles['Body2'])]
story += [Paragraph('5. Enviar arquivos e importar o kit-base', styles['H']), Paragraph('Envie MANOS-HOTSPOT-BASE.rsc, os arquivos personalizados de Ativacao e Heartbeat para a raiz da RB. Importe primeiro o kit-base. Quando terminar sem erros, envie login.html e alogin.html para flash/hotspot/, substituindo os arquivos existentes.', styles['Body2']), Paragraph('/import file-name=MANOS-HOTSPOT-BASE.rsc', styles['Code2']), Paragraph('Aguarde o terminal concluir e confira erros antes de prosseguir. Apos copiar os dois HTMLs, abra IP &gt; HotSpot &gt; Server Profiles &gt; hsprof1 e confirme html-directory=flash/hotspot.', styles['Body2'])]
story += [KeepTogether([Paragraph('6. Importar ativacao e heartbeat personalizados', styles['H']), Paragraph('/import file-name=NOME-EXATO-DA-ATIVACAO.rsc<br/>/import file-name=NOME-EXATO-DO-HEARTBEAT.rsc', styles['Code2']), Paragraph('Use os arquivos baixados agora para a identidade desta RB. A ativacao configura o RADIUS; o heartbeat cria/atualiza o script MANOS-HEARTBEAT e o scheduler de 5 segundos. Esses arquivos contem credenciais operacionais: nao os compartilhe nem os reutilize em outra RB.', styles['Body2'])])]
story += [Paragraph('7. Validar a rede antes do RADIUS', styles['H']), Paragraph('/ip address print<br/>/ip route print<br/>/interface bridge port print', styles['Code2']), Paragraph('A bridge-wan deve receber o IP e a rota default do provedor. A ether5 deve aparecer em bridge-wan, sem IP privado proprio. A bridge-livre deve conter somente a ether4 e usar 192.168.89.1/24.', styles['Body2'])]
story += [Paragraph('8. Conferir HotSpot, RADIUS e heartbeat', styles['H']), Paragraph('/system identity print<br/>/ip hotspot print detail<br/>/ip hotspot profile print detail<br/>/radius print detail<br/>/system script print detail where name="MANOS-HEARTBEAT"<br/>/system scheduler print detail where name="MANOS-HEARTBEAT"', styles['Code2']), Paragraph('Confirme a identidade correta, use-radius=yes, timeouts sem limite local e scheduler habilitado em 5s. O host/segredo RADIUS sao personalizados no servidor; nao fixe um IP neste manual. O sistema aplica os limites de sessao e velocidade salvos para a empresa/filial.', styles['Body2'])]
story += [Paragraph('9. Verificar no painel e testar', styles['H']), Paragraph('Aguarde o primeiro heartbeat, confira comunicacao e versao da RB no painel e teste portal e internet em ether2/ether3. Valide a rede livre em ether4 (192.168.89.0/24). A ether5 e uma extensao bridge da rede do provedor junto com ether1; nao recebe a faixa 192.168.89.0/24 da RB. O bloqueio gerenciado afeta as redes roteadas .88/.89, nao a bridge transparente ether5.', styles['Body2'])]
story += [Paragraph('Comandos de diagnostico', styles['H']), Paragraph('/radius print detail<br/>/ip hotspot active print detail<br/>/system script run MANOS-HEARTBEAT<br/>/log print where message~"radius|hotspot|login|failure|Manos Tech"', styles['Code2'])]
story += [Paragraph('Importante', styles['H']), Paragraph('O painel e a RB atualizam a cada 5 segundos. TX/RX representam bytes acumulados nas sessoes ativas de HotSpot desde o inicio da sessao, nao velocidade instantanea da porta WAN; sessoes encerradas deixam de compor a soma ativa. Bloqueio e reinicio ficam pendentes ate a RB confirmar a aplicacao/retorno no heartbeat. Se houver timeout RADIUS ou erro de importacao, nao repita cadastros: salve a saida do terminal/log e investigue primeiro.', styles['Body2'])]
SimpleDocTemplate(str(pdf), pagesize=A4, rightMargin=18*mm, leftMargin=18*mm, topMargin=16*mm, bottomMargin=20*mm, title='Configuracao HotSpot MikroTik Manos Tech').build(story, onFirstPage=footer, onLaterPages=footer)
print(pdf)
